1	package govflow
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	)
9	
10	// cliVoteCreateArgs 构造规格中的带委托提案：
11	// alice/bob/carol/dave 权重 300/200/100/400，bob、carol 委托给 alice，
12	// 法定人数 600，窗口 [100,200)，时间锁 300。
13	func cliVoteCreateArgs(id string) []string {
14		return []string{"create-vote", "--id", id,
15			"--member", "alice:300", "--member", "bob:200", "--member", "carol:100", "--member", "dave:400",
16			"--delegate", "bob:alice", "--delegate", "carol:alice",
17			"--quorum", "600", "--start", "100", "--deadline", "200", "--timelock", "300",
18			"--action", "transfer:audits:100"}
19	}
20	
21	// TestCLIVotePreReplaceFailureNoPartialRecord：跨进程复现标题场景。
22	// alice 在 150 的首次赞成因状态文件替换之前的保存错误失败：命令以域错误
23	// 退出码 1 结束、stdout 没有任何票据，stderr 给出具体保存原因；重新查询仍
24	// 只有 dave 在 120 的反对票。保存恢复后 160 的赞成被当作首次有效投票，
25	// 截止计票 600 赞成、400 反对、参与 1000 并通过；全过程不动资金余额、
26	// 不产生执行凭据。
27	func TestCLIVotePreReplaceFailureNoPartialRecord(t *testing.T) {
28		binary := buildCLI(t)
29		state := filepath.Join(t.TempDir(), "treasury.json")
30		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
31			t.Fatal("init failed")
32		}
33		const id = "gip-cli-savefail"
34		if _, se, code := runCLI(t, binary, state, cliVoteCreateArgs(id)...); code != 0 {
35			t.Fatalf("create-vote failed: %s", se)
36		}
37		if _, se, code := runCLI(t, binary, state, "vote", "--id", id,
38			"--voter", "dave", "--choice", "against", "--now", "120"); code != 0 {
39			t.Fatalf("dave vote failed: %s", se)
40		}
41		good, err := os.ReadFile(state)
42		if err != nil {
43			t.Fatal(err)
44		}
45	
46		// 目录不可写：CLI 进程无法创建临时文件，保存失败发生在状态文件替换之前。
47		makeDirUnwritable(t, state)
48		so, se, code := runCLI(t, binary, state, "vote", "--id", id,
49			"--voter", "alice", "--choice", "for", "--now", "150", "--json")
50		if code != 1 {
51			t.Fatalf("failed save exit=%d, want 1 (stdout=%q stderr=%q)", code, so, se)
52		}
53		// 不能返回成功票据；stderr 必须带具体保存原因，而不是投票业务拒绝。
54		if so != "" {
55			t.Fatalf("stdout must stay empty on save failure, got %q", so)
56		}
57		if !strings.Contains(se, "permission denied") {
58			t.Fatalf("stderr must carry the concrete save cause, got %q", se)
59		}
60		if strings.Contains(se, "vote rejected") {
61			t.Fatalf("a valid first vote must not be reported as a business rejection: %q", se)
62		}
63	
64		// 恢复保存条件：原文件字节未变，没有遗留临时文件。
65		if err := os.Chmod(filepath.Dir(state), 0o700); err != nil {
66			t.Fatalf("restore dir: %v", err)
67		}
68		if got, rerr := os.ReadFile(state); rerr != nil || string(got) != string(good) {
69			t.Fatalf("state file changed despite save failure")
70		}
71		if leftovers, _ := filepath.Glob(filepath.Join(filepath.Dir(state), ".govflow-state-*")); len(leftovers) != 0 {
72			t.Fatalf("failed vote left temporary file(s): %v", leftovers)
73		}
74	
75		// 查询仍只有 dave 的原记录：代表、400 权重、反对与首次时间 120；
76		// 提案仍在投票中且没有计票结论。
77		so, se, code = runCLI(t, binary, state, "proposal", "--id", id, "--json")
78		if code != 0 {
79			t.Fatalf("proposal query failed: %s", se)
80		}
81		if !strings.Contains(so, `"state": "voting"`) {
82			t.Fatalf("proposal must stay voting:\n%s", so)
83		}
84		if strings.Contains(so, `"tally"`) {
85			t.Fatalf("no tally conclusion may exist:\n%s", so)
86		}
87		if strings.Count(so, `"representative"`) != 1 ||
88			!strings.Contains(so, `"representative": "dave"`) ||
89			!strings.Contains(so, `"weight": 400`) ||
90			!strings.Contains(so, `"support": false`) ||
91			!strings.Contains(so, `"voted_at": 120`) {
92			t.Fatalf("query must show only dave's original ballot:\n%s", so)
93		}
94		if strings.Contains(so, `"representative": "alice"`) {
95			t.Fatalf("alice's 600 weight must not appear in any cast record:\n%s", so)
96		}
97	
98		// 160 再投赞成：首次有效投票，600 权重、时间 160，不能报已投过票。
99		so, se, code = runCLI(t, binary, state, "vote", "--id", id,
100			"--voter", "alice", "--choice", "for", "--now", "160", "--json")
101		if code != 0 {
102			t.Fatalf("alice first valid vote exit=%d: %s", code, se)
103		}
104		if !strings.Contains(so, `"representative": "alice"`) ||
105			!strings.Contains(so, `"weight": 600`) ||
106			!strings.Contains(so, `"voted_at": 160`) {
107			t.Fatalf("first valid vote receipt wrong:\n%s", so)
108		}
109		// 同选择重试（更晚时间）仍返回首次记录 160，不追加票据。
110		so, _, code = runCLI(t, binary, state, "vote", "--id", id,
111			"--voter", "alice", "--choice", "for", "--now", "180", "--json")
112		if code != 0 || !strings.Contains(so, `"voted_at": 160`) {
113			t.Fatalf("same-choice retry must return first record, code=%d:\n%s", code, so)
114		}
115		// 改投反对仍按既有冲突规则拒绝。
116		if _, se, code = runCLI(t, binary, state, "vote", "--id", id,
117			"--voter", "alice", "--choice", "against", "--now", "160"); code != 1 ||
118			!strings.Contains(se, "changing the vote") {
119			t.Fatalf("change vote code=%d stderr=%q, want conflict", code, se)
120		}
121	
122		// 票据顺序 dave 在前、alice 在后。
123		so, _, code = runCLI(t, binary, state, "proposal", "--id", id, "--json")
124		if code != 0 {
125			t.Fatal("proposal query failed")
126		}
127		davePos := strings.Index(so, `"representative": "dave"`)
128		alicePos := strings.Index(so, `"representative": "alice"`)
129		if davePos < 0 || alicePos < 0 || davePos > alicePos {
130			t.Fatalf("ballot order must be dave then alice:\n%s", so)
131		}
132	
133		// 截止计票：600 赞成、400 反对、参与 1000，通过。
134		so, se, code = runCLI(t, binary, state, "tally", "--id", id, "--now", "200", "--json")
135		if code != 0 {
136			t.Fatalf("tally failed: %s", se)
137		}
138		for _, want := range []string{
139			`"for_weight": 600`, `"against_weight": 400`, `"turnout": 1000`,
140			`"quorum": 600`, `"passed": true`, `"tallied_at": 200`,
141		} {
142			if !strings.Contains(so, want) {
143				t.Fatalf("tally output missing %s:\n%s", want, so)
144			}
145		}
146	
147		// 投票与计票不改变资金余额，也不生成执行凭据。
148		so, _, code = runCLI(t, binary, state, "balances", "--json")
149		if code != 0 || !strings.Contains(so, `"treasury": 1000`) || strings.Contains(so, "audits") {
150			t.Fatalf("voting/tally must not move funds, code=%d:\n%s", code, so)
151		}
152		so, _, code = runCLI(t, binary, state, "receipts", "--json")
153		if code != 0 || strings.TrimSpace(so) != "[]" {
154			t.Fatalf("voting/tally must not produce receipts, code=%d:\n%s", code, so)
155		}
156	}
157	
158	// TestCLIVotePreReplaceFailureThenDeadlineRejects：保存失败后直到 200 才再次
159	// 提交时，alice 的首次票按截止边界拒绝；dave 的旧反对票保留，到期计票只能
160	// 得到参与权重 400 的拒绝结论，资金余额不变、无执行凭据。
161	func TestCLIVotePreReplaceFailureThenDeadlineRejects(t *testing.T) {
162		binary := buildCLI(t)
163		state := filepath.Join(t.TempDir(), "treasury.json")
164		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
165			t.Fatal("init failed")
166		}
167		const id = "gip-cli-savefail-late"
168		if _, se, code := runCLI(t, binary, state, cliVoteCreateArgs(id)...); code != 0 {
169			t.Fatalf("create-vote failed: %s", se)
170		}
171		if _, se, code := runCLI(t, binary, state, "vote", "--id", id,
172			"--voter", "dave", "--choice", "against", "--now", "120"); code != 0 {
173			t.Fatalf("dave vote failed: %s", se)
174		}
175	
176		makeDirUnwritable(t, state)
177		if _, se, code := runCLI(t, binary, state, "vote", "--id", id,
178			"--voter", "alice", "--choice", "for", "--now", "150"); code != 1 ||
179			!strings.Contains(se, "permission denied") {
180			t.Fatalf("failed save code=%d stderr=%q, want concrete save cause", code, se)
181		}
182		if err := os.Chmod(filepath.Dir(state), 0o700); err != nil {
183			t.Fatalf("restore dir: %v", err)
184		}
185	
186		// 截止时刻 200 才提交：按窗口 [start,deadline) 边界拒绝。
187		_, se, code := runCLI(t, binary, state, "vote", "--id", id,
188			"--voter", "alice", "--choice", "for", "--now", "200")
189		if code != 1 || !strings.Contains(se, "not open for voting") {
190			t.Fatalf("vote at deadline code=%d stderr=%q, want window rejection", code, se)
191		}
192	
193		// 旧反对票照常保留，alice 没有任何记录。
194		so, _, code := runCLI(t, binary, state, "proposal", "--id", id, "--json")
195		if code != 0 {
196			t.Fatal("proposal query failed")
197		}
198		if strings.Count(so, `"representative"`) != 1 ||
199			!strings.Contains(so, `"representative": "dave"`) ||
200			!strings.Contains(so, `"voted_at": 120`) ||
201			strings.Contains(so, `"representative": "alice"`) {
202			t.Fatalf("only dave's ballot must remain:\n%s", so)
203		}
204	
205		// 到期计票：参与 400、未达法定人数，拒绝。
206		so, se, code = runCLI(t, binary, state, "tally", "--id", id, "--now", "200", "--json")
207		if code != 0 {
208			t.Fatalf("tally failed: %s", se)
209		}
210		for _, want := range []string{
211			`"for_weight": 0`, `"against_weight": 400`, `"turnout": 400`,
212			`"quorum": 600`, `"passed": false`,
213		} {
214			if !strings.Contains(so, want) {
215				t.Fatalf("tally output missing %s:\n%s", want, so)
216			}
217		}
218		so, _, code = runCLI(t, binary, state, "balances", "--json")
219		if code != 0 || !strings.Contains(so, `"treasury": 1000`) {
220			t.Fatalf("balances must stay unchanged, code=%d:\n%s", code, so)
221		}
222		if so, _, code = runCLI(t, binary, state, "receipts", "--json"); code != 0 ||
223			strings.TrimSpace(so) != "[]" {
224			t.Fatalf("no receipts may exist, code=%d:\n%s", code, so)
225		}
226	}
