	makeDirUnwritable(t, state)
	so, se, code := runCLI(t, binary, state, "vote", "--id", id,
		"--voter", "alice", "--choice", "for", "--now", "150", "--json")
	if code != 1 {
		t.Fatalf("failed save exit=%d, want 1 (stdout=%q stderr=%q)", code, so, se)
	}
