	if _, se, code := runCLI(t, binary, state, "vote", "--id", id,
		"--voter", "alice", "--choice", "for", "--now", "150"); code != 1 ||
		!strings.Contains(se, "permission denied") {
		t.Fatalf("failed save code=%d stderr=%q, want concrete save cause", code, se)
	}
