50	// 供保存失败后断言“成员、委托和动作内容不被失败尝试改写”。
51	func tallyExpectedMembers() map[string]MemberView {
52		return map[string]MemberView{
53			"alice": {ID: "alice", Weight: 400, Path: []string{"alice"}, Delegate: "alice", Direct: ""},
54			"bob":   {ID: "bob", Weight: 200, Path: []string{"bob", "alice"}, Delegate: "alice", Direct: "alice"},
