189		// 保存失败后不能遗留临时文件或部分文件。
190		if leftovers, _ := filepath.Glob(filepath.Join(filepath.Dir(path), ".govflow-state-*")); len(leftovers) != 0 {
191			t.Fatalf("failed commit left temporary file(s): %v", leftovers)
192		}
193	
194		// 即使目录仍不可写，只读查询看到的也是失败前的完整状态：voting、无结论。
195		v, ok, qerr := store.VoteProposal(id)
196		if qerr != nil || !ok {
197			t.Fatalf("query after failed save: ok=%v err=%v", ok, qerr)
198		}
199		if v.State != "voting" || v.Tally != nil {
200			t.Fatalf("state=%s tally=%+v, want voting with no tally conclusion", v.State, v.Tally)
201		}
202		assertTallyBallotsPreserved(t, v)
203		assertTallyProposalShape(t, v)
204		assertTallyUntouchedFunds(t, store)
205	
206		// 原状态文件保留失败前的完整内容（字节一致）。
207		if after, rerr := os.ReadFile(path); rerr != nil || string(after) != string(before) {
208			t.Fatalf("state file changed despite pre-replacement save failure")
209		}
210	
211		// 恢复保存条件，并以新进程视角重开：读到的仍是 voting、两张原票据。
212		if err := os.Chmod(filepath.Dir(path), 0o700); err != nil {
213			t.Fatalf("restore dir: %v", err)
214		}
215		if err := store.Close(); err != nil {
216			t.Fatalf("close: %v", err)
217		}
218		reopened, err := Open(path)
219		if err != nil {
220			t.Fatalf("reopen after failed tally: %v", err)
221		}
222		defer reopened.Close()
223		rv, ok, err := reopened.VoteProposal(id)
224		if err != nil || !ok {
225			t.Fatalf("query after reopen: ok=%v err=%v", ok, err)
226		}
227		if rv.State != "voting" || rv.Tally != nil {
228			t.Fatalf("after reopen state=%s tally=%+v, want voting with no conclusion", rv.State, rv.Tally)
229		}
230		assertTallyBallotsPreserved(t, rv)
231		assertTallyProposalShape(t, rv)
232	
233		// 210 再次计票才形成首次成功结论：通过、700/300/1000，首次计票时间是 210，
234		// 绝不沿用失败尝试的 200；它必须真正落盘（先前内存里已经算出通过，不能
235		// 因此跳过保存或把这次调用当成“已有结论”的重试）。
236		res210, err := reopened.TallyVote(id, 210)
237		if err != nil {
238			t.Fatalf("first successful tally after recovery at 210: %v", err)
239		}
240		if !res210.Passed || res210.ForWeight != 700 || res210.AgainstWeight != 300 ||
241			res210.Turnout != 1000 || res210.Quorum != 600 || res210.TalliedAt != 210 {
242			t.Fatalf("tally at 210 = %+v, want passed for=700 against=300 turnout=1000 tallied_at=210", res210)
243		}
244		sv, ok, err := reopened.VoteProposal(id)
245		if err != nil || !ok {
246			t.Fatalf("query after 210 tally: ok=%v err=%v", ok, err)
247		}
248		if sv.State != "passed" || sv.Tally == nil || !sv.Tally.Passed ||
249			sv.Tally.ForWeight != 700 || sv.Tally.AgainstWeight != 300 ||
250			sv.Tally.Turnout != 1000 || sv.Tally.TalliedAt != 210 {
251			t.Fatalf("after 210 tally state=%s tally=%+v, want passed with tallied_at=210", sv.State, sv.Tally)
252		}
253		assertTallyBallotsPreserved(t, sv)
254		assertTallyProposalShape(t, sv)
255		assertTallyUntouchedFunds(t, reopened)
256	
257		// 再次计票返回 210 的首次结论，不随新时间改变。
258		again, err := reopened.TallyVote(id, 300)
259		if err != nil {
260			t.Fatalf("repeat tally after success: %v", err)
261		}
262		if !again.Passed || again.TalliedAt != 210 || again.ForWeight != 700 || again.AgainstWeight != 300 {
263			t.Fatalf("repeat tally = %+v, want first successful 210 conclusion", again)
264		}
265	}
266	
267	// assertNoTallyLeftovers 断言没有计票提交遗留的临时状态文件。
268	func assertNoTallyLeftovers(t *testing.T, path string) {
269		t.Helper()
270		if leftovers, _ := filepath.Glob(filepath.Join(filepath.Dir(path), ".govflow-state-*")); len(leftovers) != 0 {
271			t.Fatalf("failed commit left temporary file(s): %v", leftovers)
272		}
273	}
274	
275	// TestTallyDirSyncFailureWrittenButUnconfirmed：首次计票时状态文件已替换
276	// 成功、只在之后的目录同步失败（目录可写可进入但不可读，0o300）时，
277	// TallyVote 必须：
278	//   - 仍没有成功计票结果返回（nil），但错误能识别为
279	//     ErrDurabilityUnconfirmed（*DurabilityError），并保留具体失败原因；
280	//   - 查询应看到 passed 状态与 200 的首次结论——首次结论、计票时间与提案
281	//     状态其实已一起写入；票据与资金记录仍保持一致；
282	//   - 保存条件恢复后在 210 再次计票，应返回已经写入的 200 结论，而不是
283	//     重新算一个 210，也不报错。
284	func TestTallyDirSyncFailureWrittenButUnconfirmed(t *testing.T) {
285		store, path := tallySetup(t, "gip-tally-dirsync")
286		const id = "gip-tally-dirsync"
287		defer store.Close()
288	
289		makeDirSyncFail(t, path)
290		res, err := store.TallyVote(id, 200)
291		if err == nil {
292			t.Fatal("expected durability warning error, got nil")
293		}
294		// 调用本身没有成功计票结果：结论已落盘，但这次写入的持久性未确认。
295		if res != nil {
296			t.Fatalf("durability-uncertain call must not report a successful result: %+v", res)
297		}
298		if !errors.Is(err, ErrDurabilityUnconfirmed) {
299			t.Fatalf("err = %v, want errors.Is ErrDurabilityUnconfirmed", err)
300		}
301		var derr *DurabilityError
302		if !errors.As(err, &derr) || derr.Cause == nil {
303			t.Fatalf("err = %v (%T), want *DurabilityError with concrete cause", err, err)
304		}
305		if !strings.Contains(err.Error(), derr.Cause.Error()) {
306			t.Fatalf("err %q must preserve the underlying save failure %q", err, derr.Cause)
307		}
308		assertNoTallyLeftovers(t, path)
309	
310		// 恢复目录后查询：passed 状态与 200 的首次结论已写入，票据保持一致。
311		if err := os.Chmod(filepath.Dir(path), 0o700); err != nil {
312			t.Fatalf("restore dir: %v", err)
313		}
314		v, ok, qerr := store.VoteProposal(id)
315		if qerr != nil || !ok {
316			t.Fatalf("query after durability warning: ok=%v err=%v", ok, qerr)
317		}
318		if v.State != "passed" || v.Tally == nil {
319			t.Fatalf("state=%s tally=%+v, want passed with the written 200 conclusion", v.State, v.Tally)
320		}
321		if !v.Tally.Passed || v.Tally.ForWeight != 700 || v.Tally.AgainstWeight != 300 ||
322			v.Tally.Turnout != 1000 || v.Tally.Quorum != 600 || v.Tally.TalliedAt != 200 {
323			t.Fatalf("written tally = %+v, want passed for=700 against=300 turnout=1000 tallied_at=200", v.Tally)
324		}
325		assertTallyBallotsPreserved(t, v)
326		assertTallyProposalShape(t, v)
327		assertTallyUntouchedFunds(t, store)
328	
329		// 以全新进程视角重开，写入的结论必须能跨进程读到，且通过严格重放校验。
330		if err := store.Close(); err != nil {
331			t.Fatalf("close: %v", err)
332		}
333		reopened, err := Open(path)
334		if err != nil {
335			t.Fatalf("reopen after durability-uncertain tally: %v", err)
336		}
337		defer reopened.Close()
338		rv, ok, err := reopened.VoteProposal(id)
339		if err != nil || !ok {
340			t.Fatalf("query after reopen: ok=%v err=%v", ok, err)
341		}
342		if rv.State != "passed" || rv.Tally == nil || !rv.Tally.Passed || rv.Tally.TalliedAt != 200 {
343			t.Fatalf("after reopen state=%s tally=%+v, want passed with tallied_at=200", rv.State, rv.Tally)
344		}
345		assertTallyBallotsPreserved(t, rv)
346	
347		// 210 再次计票：返回已经写入的 200 结论，不重新计票、不改首次时间。
348		again, err := reopened.TallyVote(id, 210)
349		if err != nil {
350			t.Fatalf("repeat tally after recovery: %v", err)
351		}
352		if !again.Passed || again.ForWeight != 700 || again.AgainstWeight != 300 ||
353			again.Turnout != 1000 || again.Quorum != 600 || again.TalliedAt != 200 {
354			t.Fatalf("repeat tally = %+v, want the already-written 200 conclusion", again)
355		}
356		// 查询结论与首次结论一致，资金仍未被计票触动。
357		fv, _, err := reopened.VoteProposal(id)
358		if err != nil {
359			t.Fatal(err)
360		}
361		if fv.State != "passed" || fv.Tally == nil || fv.Tally.TalliedAt != 200 {
362			t.Fatalf("state=%s tally=%+v, want passed tallied_at=200", fv.State, fv.Tally)
363		}
364		assertTallyUntouchedFunds(t, reopened)
365	}
