384			if !strings.Contains(out, `"passed": true`) {
385				t.Fatalf("tally %d diverged or failed: %s", i, out)
386			}
387			m := tallyTimeRe.FindStringSubmatch(out)
388			if m == nil {
389				t.Fatalf("tally %d missing tallied_at: %s", i, out)
390			}
391			if winner == "" {
392				winner = m[1]
393			} else if m[1] != winner {
394				t.Fatalf("tally %d tallied_at=%s, want first result %s", i, m[1], winner)
395			}
396		}
397		so, _, _ := runCLI(t, binary, state, "proposal", "--id", "gip-c", "--json")
398		if strings.Count(so, `"voted_at"`) != 1 {
399			t.Fatalf("ballot records changed under concurrent tally:\n%s", so)
400		}
401	}
