760			},
761			{
762				name:    "index-missing",
763				edit:    func(s string) string { return strings.Replace(s, `"index": 0,`, ``, 1) },
764				wantMsg: []string{"corrupt", "gip-1", "action 0", `"index"`, "missing"},
765			},
766		}
767		for _, tc := range cases {
768			t.Run(tc.name, func(t *testing.T) {
769				corrupt := tc.edit(string(raw))
770				if corrupt == string(raw) {
771					t.Fatalf("setup: target field not found")
772				}
773				bad := filepath.Join(dir, tc.name+".json")
774				if err := os.WriteFile(bad, []byte(corrupt), 0o600); err != nil {
775					t.Fatal(err)
776				}
777				for _, args := range [][]string{
778					{"receipt", "--id", "gip-1"},
779					{"receipt", "--id", "gip-1", "--json"},
780					{"receipts"},
781					{"receipts", "--json"},
782					{"balances", "--json"},
783					{"proposals", "--json"},
784				} {
785					so, se, code := runCLI(t, binary, bad, args...)
786					if code != 1 {
787						t.Fatalf("%v exit=%d want 1, stdout=%q stderr=%q", args, code, so, se)
788					}
789					if so != "" {
790						t.Fatalf("%v stdout must stay empty on corruption, got %q", args, so)
791					}
792					for _, want := range tc.wantMsg {
793						if !strings.Contains(se, want) {
794							t.Fatalf("%v stderr %q missing %q", args, se, want)
795						}
796					}
797				}
798				// 不整理、补齐或覆盖缺损文件。
799				if got, err := os.ReadFile(bad); err != nil || string(got) != corrupt {
800					t.Fatalf("corrupt file was modified or rewritten")
801				}
802			})
