275			ProposalID string `json:"proposal_id"`
276			ExecutedAt int64  `json:"executed_at"`
277			Order      int64  `json:"order"`
278			Actions    []struct {
279				Action   string `json:"action"`
280				Treasury struct {
281					Before int64 `json:"before"`
282					After  int64 `json:"after"`
283				} `json:"treasury"`
284			} `json:"actions"`
285		}
