298		if err := os.Chmod(filepath.Dir(state), 0o700); err != nil {
299			t.Fatalf("restore dir: %v", err)
300		}
301	
302		// 告警不撤销转账：两份凭据都可查询，余额与动作留痕对应。
303		so, _, code = runCLI(t, binary, state, "balances", "--json")
304		if code != 0 || !strings.Contains(so, `"treasury": 700`) ||
305			!strings.Contains(so, `"audits": 250`) || !strings.Contains(so, `"legal": 50`) {
306			t.Fatalf("balances after warning = code %d:\n%s", code, so)
307		}
308		so, _, code = runCLI(t, binary, state, "receipts", "--json")
309		if code != 0 || strings.Count(so, `"proposal_id"`) != 2 {
310			t.Fatalf("receipts after warning = code %d:\n%s", code, so)
311		}
312		// 再次执行同一编号（不同时间）只取得原来的首次凭据，退出码 0，不再次扣款。
313		so, _, code = runCLI(t, binary, state, "execute", "--id", "gip-1", "--now", "999", "--json")
314		if code != 0 || !strings.Contains(so, `"executed_at": 150`) {
315			t.Fatalf("re-execute must return the first receipt, code %d:\n%s", code, so)
316		}
317		so, _, _ = runCLI(t, binary, state, "balances", "--json")
318		if !strings.Contains(so, `"treasury": 700`) {
319			t.Fatalf("re-execute must not debit again:\n%s", so)
320		}
321	}
