111	// TestCLITallyFirstCountBaseline：正常在截止时刻 200 首次计票的命令行基线：
112	// 普通文本与 --json 都以退出码 0 给出赞成 600、反对 400、参与 1000 的通过
113	// 结论，首次计票时间为 200；再次计票（即使更晚）返回同一结论；计票不执行
114	// 转账、不产生执行凭据。这是两类保存失败场景共同的对照。
115	func TestCLITallyFirstCountBaseline(t *testing.T) {
116		binary := buildCLI(t)
117		state := filepath.Join(t.TempDir(), "treasury.json")
118		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
119			t.Fatal("init failed")
120		}
121		const id = "gip-cli-tally-ok"
122		cliTallyPrepare(t, binary, state, id)
123	
124		// 普通文本：单行给出完整通过结论与首次计票时间。
125		so, se, code := runCLI(t, binary, state, "tally", "--id", id, "--now", "200")
126		if code != 0 {
127			t.Fatalf("first tally exit=%d: %s", code, se)
128		}
129		if !strings.Contains(so, "tally proposal="+id+
130			" for=600 against=400 turnout=1000 quorum=600 => passed (tallied_at=200)") {
131			t.Fatalf("text tally output wrong:\n%s", so)
132		}
133	
134		// 再次计票（--json、更晚的 210）返回首次 200 结论，不重新计票。
135		so, se, code = runCLI(t, binary, state, "tally", "--id", id, "--now", "210", "--json")
136		if code != 0 {
137			t.Fatalf("repeat tally exit=%d: %s", code, se)
138		}
139		assertCLITallyPassedJSON(t, so, "200")
140	
141		// 查询：passed 状态、200 的首次结论、两张原票据与委托关系全部保留。
142		so, se, code = runCLI(t, binary, state, "proposal", "--id", id, "--json")
143		if code != 0 {
144			t.Fatalf("proposal query exit=%d: %s", code, se)
145		}
146		if !strings.Contains(so, `"state": "passed"`) {
147			t.Fatalf("proposal must be passed:\n%s", so)
148		}
149		assertCLITallyPassedJSON(t, so, "200")
150		assertCLITallyBallotsJSON(t, so)
151	
152		so, se, code = runCLI(t, binary, state, "proposal", "--id", id)
153		if code != 0 {
154			t.Fatalf("text proposal query exit=%d: %s", code, se)
155		}
156		if !strings.Contains(so, "state=passed") ||
157			!strings.Contains(so, "tally for=600 against=400 turnout=1000 => passed tallied_at=200") {
158			t.Fatalf("text query must show the passed conclusion:\n%s", so)
159		}
160		assertCLITallyShapeText(t, so)
161		assertCLITallyFundsUntouched(t, binary, state)
162	}
163	
164	// TestCLITallyPreReplaceFailureLeavesNoConclusion：首次计票的保存失败发生在
165	// 状态文件替换之前（目录不可写，临时文件无法创建）时，普通文本与 --json 的
166	// tally 都以退出码 1 结束，标准输出没有计票结果，标准错误保留具体保存原因
167	// ——不能说成投票尚未截止，也不能说成结论已写入。随后查询仍显示 voting、
168	// 没有计票结论；恢复保存条件后在 210 再次计票才产生首次通过结论，首次计票
169	// 时间为 210，不沿用失败尝试的 200。
170	func TestCLITallyPreReplaceFailureLeavesNoConclusion(t *testing.T) {
171		binary := buildCLI(t)
172		state := filepath.Join(t.TempDir(), "treasury.json")
173		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
174			t.Fatal("init failed")
175		}
176		const id = "gip-cli-tally-pre"
177		cliTallyPrepare(t, binary, state, id)
178	
179		// 记录失败前的完整状态文件字节：保存失败后它必须原样保留。
180		before, err := os.ReadFile(state)
181		if err != nil {
182			t.Fatal(err)
183		}
184	
185		// 目录不可写：提交在状态文件替换之前（创建临时文件）失败。
186		makeDirUnwritable(t, state)
187		for _, args := range [][]string{
188			{"tally", "--id", id, "--now", "200"},
189			{"tally", "--id", id, "--now", "200", "--json"},
190		} {
191			so, se, code := runCLI(t, binary, state, args...)
192			if code != 1 {
193				t.Fatalf("%v exit=%d, want 1 (stdout=%q stderr=%q)", args, code, so, se)
194			}
195			if so != "" {
196				t.Fatalf("%v stdout must carry no tally result, got %q", args, so)
197			}
198			if !strings.Contains(se, "permission denied") {
199				t.Fatalf("%v stderr must keep the concrete save cause, got %q", args, se)
200			}
201			if strings.Contains(se, "still open") {
202				t.Fatalf("%v a deadline-reached tally must not be reported as not yet closed: %q", args, se)
203			}
204			if strings.Contains(se, "durability not confirmed") {
205				t.Fatalf("%v nothing was written; must not claim a written conclusion: %q", args, se)
206			}
207		}
208	
209		// 恢复保存条件：原文件字节未变，没有遗留临时文件。
210		if err := os.Chmod(filepath.Dir(state), 0o700); err != nil {
211			t.Fatalf("restore dir: %v", err)
212		}
213		if got, rerr := os.ReadFile(state); rerr != nil || string(got) != string(before) {
214			t.Fatalf("state file changed despite pre-replacement save failure")
215		}
216		if leftovers, _ := filepath.Glob(filepath.Join(filepath.Dir(state), ".govflow-state-*")); len(leftovers) != 0 {
217			t.Fatalf("failed tally left temporary file(s): %v", leftovers)
218		}
219	
220		// 随后查询仍显示 voting、没有计票结论；两张原票据与委托关系保持原样。
221		so, se, code := runCLI(t, binary, state, "proposal", "--id", id, "--json")
222		if code != 0 {
223			t.Fatalf("proposal query exit=%d: %s", code, se)
224		}
225		if !strings.Contains(so, `"state": "voting"`) {
226			t.Fatalf("proposal must stay voting:\n%s", so)
227		}
228		if strings.Contains(so, `"tally"`) {
229			t.Fatalf("no tally conclusion may exist:\n%s", so)
230		}
231		assertCLITallyBallotsJSON(t, so)
232	
233		so, se, code = runCLI(t, binary, state, "proposal", "--id", id)
234		if code != 0 {
235			t.Fatalf("text proposal query exit=%d: %s", code, se)
236		}
237		if !strings.Contains(so, "state=voting") || strings.Contains(so, "tally for=") {
238			t.Fatalf("text query must show voting with no tally line:\n%s", so)
239		}
240		assertCLITallyShapeText(t, so)
241		assertCLITallyFundsUntouched(t, binary, state)
242	
243		// 恢复保存条件后在 210 再次计票：才产生首次通过结论，首次计票时间是 210，
244		// 绝不沿用失败尝试的 200。
245		so, se, code = runCLI(t, binary, state, "tally", "--id", id, "--now", "210", "--json")
246		if code != 0 {
247			t.Fatalf("first successful tally at 210 exit=%d: %s", code, se)
248		}
249		assertCLITallyPassedJSON(t, so, "210")
250		if strings.Contains(so, `"tallied_at": 200`) {
251			t.Fatalf("must not reuse the failed attempt's 200:\n%s", so)
252		}
253	
254		// 再次计票返回 210 的首次结论，不随新时间改变；资金仍未被触动。
255		so, se, code = runCLI(t, binary, state, "tally", "--id", id, "--now", "300")
256		if code != 0 {
257			t.Fatalf("repeat tally exit=%d: %s", code, se)
258		}
259		if !strings.Contains(so, "tallied_at=210") {
260			t.Fatalf("repeat tally must return the first 210 conclusion:\n%s", so)
261		}
262		assertCLITallyFundsUntouched(t, binary, state)
263	}
264	
265	// TestCLITallyDirSyncFailureWrittenButUnconfirmed：首次计票时状态文件已替换
266	// 成功、只在随后的目录同步失败（目录可写可进入但不可读，0o300）时，普通文本
267	// 与 --json 的 tally 同样以退出码 1 结束，标准输出仍没有计票结果，标准错误
268	// 说明“已写入但持久性未确认”并保留具体原因。恢复正常读取条件后，查询应显示
269	// passed 和首次计票时间为 200 的完整结论；在 210 再次计票应正常返回这份已有
270	// 结论，不改成 210，也不把已通过提案退回 voting。
271	func TestCLITallyDirSyncFailureWrittenButUnconfirmed(t *testing.T) {
272		binary := buildCLI(t)
273		state := filepath.Join(t.TempDir(), "treasury.json")
274		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
275			t.Fatal("init failed")
276		}
277		// 同一状态文件中的两项相同提案分别覆盖普通文本与 --json：
278		// 各自的首次计票都遇到目录同步失败。
279		const idText = "gip-cli-tally-sync-text"
280		const idJSON = "gip-cli-tally-sync-json"
281		cliTallyPrepare(t, binary, state, idText)
282		cliTallyPrepare(t, binary, state, idJSON)
283	
284		makeDirSyncFail(t, state)
285	
286		// 普通文本：退出码 1，stdout 没有计票结果，stderr 说明已写入但持久性未确认。
287		so, se, code := runCLI(t, binary, state, "tally", "--id", idText, "--now", "200")
288		if code != 1 {
289			t.Fatalf("text tally exit=%d, want 1 (stdout=%q stderr=%q)", code, so, se)
290		}
291		if so != "" {
292			t.Fatalf("stdout must carry no tally result on durability warning, got %q", so)
293		}
294		if !strings.Contains(se, "durability not confirmed") ||
295			!strings.Contains(se, "permission denied") {
296			t.Fatalf("stderr must state written-but-unconfirmed with the concrete cause, got %q", se)
297		}
298		if strings.Contains(se, "still open") {
299			t.Fatalf("a deadline-reached tally must not be reported as not yet closed: %q", se)
300		}
301	
302		// --json：同样退出码 1、stdout 没有计票结果对象，stderr 保留同一告警。
303		so, se, code = runCLI(t, binary, state, "tally", "--id", idJSON, "--now", "200", "--json")
304		if code != 1 {
305			t.Fatalf("json tally exit=%d, want 1 (stdout=%q stderr=%q)", code, so, se)
306		}
307		if so != "" {
308			t.Fatalf("json stdout must carry no tally result on durability warning, got %q", so)
309		}
310		if !strings.Contains(se, "durability not confirmed") {
311			t.Fatalf("json stderr must state the durability warning, got %q", se)
312		}
313	
314		// 改名已成功：没有遗留临时文件。恢复正常读取条件。
315		if leftovers, _ := filepath.Glob(filepath.Join(filepath.Dir(state), ".govflow-state-*")); len(leftovers) != 0 {
316			t.Fatalf("failed dir sync left temporary file(s): %v", leftovers)
317		}
318		if err := os.Chmod(filepath.Dir(state), 0o700); err != nil {
319			t.Fatalf("restore dir: %v", err)
320		}
321	
322		// 查询：两项提案都显示 passed 和首次计票时间 200 的完整结论，
323		// 原票据、委托关系与动作原文保持原样。
324		for _, id := range []string{idText, idJSON} {
325			so, se, code = runCLI(t, binary, state, "proposal", "--id", id, "--json")
326			if code != 0 {
327				t.Fatalf("proposal %s query exit=%d: %s", id, code, se)
328			}
329			if !strings.Contains(so, `"state": "passed"`) {
330				t.Fatalf("proposal %s must show the written passed state:\n%s", id, so)
331			}
332			assertCLITallyPassedJSON(t, so, "200")
333			assertCLITallyBallotsJSON(t, so)
334	
335			so, se, code = runCLI(t, binary, state, "proposal", "--id", id)
336			if code != 0 {
337				t.Fatalf("text proposal %s query exit=%d: %s", id, code, se)
338			}
339			if !strings.Contains(so, "state=passed") ||
340				!strings.Contains(so, "tally for=600 against=400 turnout=1000 => passed tallied_at=200") {
341				t.Fatalf("text query for %s must show the written 200 conclusion:\n%s", id, so)
342			}
343			assertCLITallyShapeText(t, so)
344		}
345	
346		// 在 210 再次计票：正常返回已经写入的 200 结论（退出码 0），不改成 210，
347		// 也不把已通过提案退回 voting。
348		so, se, code = runCLI(t, binary, state, "tally", "--id", idText, "--now", "210")
349		if code != 0 {
350			t.Fatalf("repeat tally exit=%d: %s", code, se)
351		}
352		if !strings.Contains(so, "=> passed (tallied_at=200)") {
353			t.Fatalf("repeat tally must return the already-written 200 conclusion:\n%s", so)
354		}
355		so, se, code = runCLI(t, binary, state, "tally", "--id", idJSON, "--now", "210", "--json")
356		if code != 0 {
357			t.Fatalf("repeat json tally exit=%d: %s", code, se)
358		}
359		assertCLITallyPassedJSON(t, so, "200")
360	
361		so, se, code = runCLI(t, binary, state, "proposal", "--id", idText, "--json")
362		if code != 0 {
363			t.Fatalf("proposal query exit=%d: %s", code, se)
364		}
365		if !strings.Contains(so, `"state": "passed"`) || !strings.Contains(so, `"tallied_at": 200`) {
366			t.Fatalf("passed proposal must not fall back to voting or move to 210:\n%s", so)
367		}
368		assertCLITallyFundsUntouched(t, binary, state)
369	}
